from pathlib import Path
import pandas as pd,numpy as np,json
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parent;O=R/'results'
p=pd.read_csv(O/'prevalence_by_outcome.csv');c=pd.read_csv(O/'helpful_vs_harmful.csv');counts=pd.read_csv(O/'outcome_counts.csv');dist=pd.read_csv(O/'label_distribution.csv');joint=pd.read_csv(O/'joint_distribution.csv');bal=pd.read_csv(O/'equal_cell_sensitivity.csv');breaks=pd.read_csv(O/'breakdowns.csv')
names={'qwen122':'Qwen122 annotations','gemma':'Gemma31B annotations','qwen':'Qwen27B annotations','majority':'Majority labels','labelled_similarity':'Labelled similarity','important_contrast':'Important contrast','helped':'Improved','harmed':'Worsened','unchanged':'Unchanged'}
fig,axs=plt.subplots(2,2,figsize=(12,8),sharey=True)
for ax,ann in zip(axs.flat,['qwen122','gemma','qwen','majority']):
 for ei,(ev,color) in enumerate([('helped','#2d8963'),('harmed','#c75e54'),('unchanged','#8493a4')]):
  v=p[(p.policy=='judge50_direct')&(p.cohort=='all')&(p.annotator==ann)&(p.outcome==ev)].set_index('label').loc[['labelled_similarity','important_contrast']]
  val=v.label_yes_fraction.to_numpy()*100;x=np.arange(2)+(ei-1)*.24;err=np.stack([(v.label_yes_fraction-v.lo).to_numpy()*100,(v.hi-v.label_yes_fraction).to_numpy()*100])
  ax.bar(x,val,.22,color=color,label=names[ev],yerr=err,capsize=2)
  for xx,yy in zip(x,val):ax.text(xx,yy+2,f'{yy:.1f}',ha='center',fontsize=9)
 ax.set_xticks([0,1]);ax.set_xticklabels(['Labelled similarity','Important contrast']);ax.set_ylim(0,105);ax.set_ylabel('Label present within this outcome (%)');ax.set_title(names[ann]);ax.grid(axis='y',alpha=.15);ax.set_axisbelow(True)
axs[0,0].legend(fontsize=9,loc='upper right');fig.suptitle('Which labels occur more in helpful versus harmful NN changes?',fontsize=15)
fig.text(.5,.012,'Original control vs NN judge decisions at a common 50 cutoff. Design-weighted rates; 95% target-cluster intervals. Unchanged shown as context.',ha='center',fontsize=9)
fig.tight_layout(rect=[0,.04,1,.95]);fig.savefig(O/'labels_by_outcome.png',dpi=180);fig.savefig(O/'labels_by_outcome.pdf');plt.close(fig)
def table(df,percent=()):
 x=df.copy()
 for k in percent:x[k]=x[k].map(lambda v:'—' if pd.isna(v) else f'{100*v:.1f}')
 return x.to_html(index=False,border=0,na_rep='—')
parts=['''<!doctype html><html lang="en"><meta charset="utf-8"><title>NN labels in improved, worsened and unchanged decisions</title><style>body{font:16px system-ui;max-width:1250px;margin:40px auto;padding:0 24px;color:#172c3d}p,li{line-height:1.5}table{border-collapse:collapse;width:100%;margin:20px 0;font-size:14px}td,th{padding:9px;border-bottom:1px solid #dce5eb;text-align:right}td:first-child,th:first-child{text-align:left}th{background:#eef4f7}img{max-width:100%}.note{background:#edf3f7;padding:16px;border-radius:6px}details{margin:20px 0}summary{cursor:pointer;font-weight:600}h2{margin-top:35px}</style><h1>Labels in improved, worsened and unchanged decisions</h1><p>The main question is now: <b>Does a label appear more often when adding an NN fixes a mistake than when it creates a mistake?</b> We compare the original probability-only control and NN answers on the exact same cases.</p><div class="note">Improved: control wrong, NN correct. Worsened: control correct, NN wrong. Unchanged: same binary answer, whether right or wrong. The main comparison thresholds both original LLM probabilities at 50. It does not count an unqueried pipeline referral as an unchanged LLM answer. Both scores were actually collected for these cases. The original pipeline and matched-tuning views remain below.</div>''']
parts.append('<h2>Main result</h2><p>With majority labels, <b>labelled similarity is present in 81.8% of improvements versus 50.4% of worsening</b>. <b>Important contrast is present in 20.7% of improvements versus 54.2% of worsening</b>. Both directions agree across all three annotators and persist in the pipeline and matched-threshold sensitivities. This supports the similarity enrichment prediction; the contrast enrichment prediction goes in the opposite direction in this direct comparison. Unchanged cases are shown for context.</p><p>These are descriptive outcome-group comparisons. Contrast may identify difficult or misleading-neighbour cases; greater prevalence among worsening does not establish that contrast itself causes errors. Equal-cell comparisons reduce differences in dataset/model composition and retain the same directions.</p>')
parts.append('<h2>Overall label distribution</h2><p>Counts are over 25,000 target–neighbour contexts, not repeated outcome judges. Labels can co-occur.</p>')
parts.append(table(dist[dist.annotator=='majority'][['label','value','n','fraction']],['fraction']))
parts.append('<details><summary>Joint labels and distribution for each annotation model</summary>'+table(joint,['fraction'])+table(dist,['fraction'])+'</details>')
parts.append('<h2>Labels within each outcome</h2><img src="labels_by_outcome.png" alt="Label prevalence in improved, worsened and unchanged original judge decisions">')
for cohort in ['all','toxicity4']:
 parts.append('<h3>'+('All ten datasets' if cohort=='all' else 'Four toxicity / content-safety datasets')+'</h3>')
 v=p[(p.policy=='judge50_direct')&(p.cohort==cohort)&(p.annotator=='majority')&p.outcome.isin(['helped','harmed','unchanged'])].pivot(index='label',columns='outcome',values='label_yes_fraction').reset_index();v=v[['label','helped','harmed','unchanged']];v['helped_minus_harmed']=v.helped-v.harmed;parts.append(table(v,['helped','harmed','unchanged','helped_minus_harmed']))
 parts.append('<p>Entries are the percentage of each outcome group labelled YES. The last column is the improved-minus-worsened prevalence difference, in percentage points. It is not a change in accuracy.</p>')
 parts.append(table(counts[(counts.policy=='judge50_direct')&(counts.cohort==cohort)&counts.outcome.isin(['helped','harmed','unchanged'])][['outcome','judgment_count','contexts','weighted_share']],['weighted_share']))
parts.append('<h2>Does the comparison agree across annotators?</h2>')
v=c[(c.policy=='judge50_direct')&(c.cohort=='all')];parts.append(table(v[['annotator','label','helped_minus_harmed','lo','hi']],['helped_minus_harmed','lo','hi']))
parts.append('<p>Positive means the label is more frequent among improvements than worsening. Negative means the opposite. 95% intervals cluster all repeated observations of the same target text. These are descriptive associations, not evidence that a feature caused the change.</p>')
parts.append('<details><summary>Unchanged-correct versus unchanged-wrong</summary>'+table(p[(p.policy=='judge50_direct')&(p.cohort=='all')&(p.annotator=='majority')&p.outcome.isin(['stable_correct','stable_wrong'])][['label','outcome','valid_judgments','label_yes_fraction']],['label_yes_fraction'])+'</details>')
parts.append('<h2>Pipeline and matched-threshold sensitivity</h2><p>Fixed50 pipeline applies probe50 before judge50; a non-referred case cannot change its pipeline prediction. Matched tuning transfers the same pair of probe/judge thresholds to both control and NN, under each of three validation-selected anchors. Its rates combine those three binary comparisons with equal weight; unchanged/improved/worsened are never assigned to an averaged probability. No new thresholds are fitted.</p>')
for policy in ['fixed50','anchor_average']:
 parts.append('<h3>'+policy+'</h3>');v=p[(p.policy==policy)&(p.cohort=='all')&(p.annotator=='majority')&p.outcome.isin(['helped','harmed','unchanged'])].pivot(index='label',columns='outcome',values='label_yes_fraction').reset_index();parts.append(table(v,['helped','harmed','unchanged']))
parts.append('<details><summary>Equal-cell sensitivity: compare only cells with both improvements and worsening</summary><p>Each outcome judge/backbone/dataset cell receives equal weight after computing its within-cell label prevalences. Cells lacking one event are excluded from this sensitivity, not the primary analysis.</p>'+table(bal[(bal.cohort=='all')&(bal.annotator=='majority')],['helped_yes','harmed_yes','difference'])+'</details>')
for dim in ['model','dataset','backbone','label_aligned']:
 v=breaks[(breaks.policy=='judge50_direct')&(breaks.cohort=='all')&(breaks.dimension==dim)].pivot(index=['group','label'],columns='outcome',values='label_yes_fraction').reset_index();v['difference']=v.helped-v.harmed
 parts.append('<details><summary>Breakdown by '+dim+'</summary>'+table(v,['helped','harmed','unchanged','difference'])+'</details>')
parts.append('<h2>Method and limits</h2><ul><li>Use original design weights, normalize within outcome judge/backbone/dataset cell, then condition on the event. An event group can have a different mix of datasets and difficulties from another; equal-cell sensitivity is supplied.</li><li>All six local outcome judges and the four prior API judges are retained, with each model’s original three-condition valid-pair selection. There are 240,524 valid judge–context pairs, from 25,000 NN contexts.</li><li>Uncertain, unresolved and missing annotations are explicitly excluded from YES-versus-NO percentages, with exclusion counts in the data files. They are not silently coded NO.</li><li>The two labels are independent questions and may both be YES. The three outcome categories are exhaustive; their associations are consequently related.</li><li>“No change” means unchanged binary classification; the numeric probability may have moved.</li><li>Labelled similarity is not a direct measurement of ambiguity, and contrast presence does not establish correct use. This analysis tests associations; it does not establish internal reasoning or causal mechanisms.</li></ul><p><a href="prevalence_by_outcome.csv">Full label-by-outcome results</a> · <a href="helpful_vs_harmful.csv">Helpful-versus-harmful differences and intervals</a> · <a href="outcome_given_label.csv">Reverse conditional: outcome probabilities given labels</a> · <a href="label_distribution.csv">Label distribution</a> · <a href="labels_by_outcome.pdf">Plot PDF</a></p></html>')
(O/'report.html').write_text(''.join(parts));print(O/'report.html')
